import { MEDIA_DRILLDOWN_KPI_KEYS } from '../constants';
import {
  hasMediaDrilldownChartData,
  MediaDrilldownChartEntry,
} from './hasMediaDrilldownChartData';

export const hasMediaDrilldownData = (
  chartData: Record<string, MediaDrilldownChartEntry | undefined>,
): boolean =>
  MEDIA_DRILLDOWN_KPI_KEYS.some((key) =>
    hasMediaDrilldownChartData(chartData[key]),
  );
